cssAppend:
/* story-form-17 — clear mediate echo after yield; Volume accept first */
body.rp-cold-yielded .rp-day2-line,
body.rp-cold-yielded .rp-npc-remember,
body.rp-cold-yielded [data-testid="story-day2-orhan-line"],
body.rp-cold-yielded [data-testid="story-day2-orhan-forbidden"],
body.rp-cold-yielded [data-testid="story-day2-cem-rehearsal"],
body.rp-cold-yielded .rp-stage-prop--shared-string,
body.rp-cold-yielded .rp-stage-prop--kite-high,
body.rp-cold-yielded .rp-stage-prop--chalk-cup,
body.rp-cold-yielded .rp-hotspot__bubble[data-testid="story-day2-orhan-line"],
body.rp-cold-yielded .rp-hotspot__bubble[data-testid="story-day2-orhan-forbidden"],
body.rp-cold-yielded .rp-hotspot__bubble[data-testid="story-day2-cem-rehearsal"] {
  display: none !important;
}
/* Volume accept panel stacks above other evening CTAs */
.rp-evening-volume-accept {
  order: -1;
  position: relative;
  z-index: 5;
}
body.rp-volume-pending-accept [data-testid="evening-headphones-street-job"],
body.rp-volume-pending-accept [data-next="headphones"] {
  /* street job not primary until accept — demote if wrongly painted */
  opacity: 0.55;
  pointer-events: none;
}
body.rp-volume-accepted [data-next="headphones"],
body.rp-volume-accepted [data-testid="evening-headphones-street-job"] {
  opacity: 1;
  pointer-events: auto;
}

integratorSnippet.pseudo:
function storyForm17() {
  return state.questPack?.storyForm17 || state.storyForm17 || null;
}

function coldEchoSuppressed() {
  const day = state.save.dayIndex || 1;
  if (day >= 7) return true;
  if (["cold_day2_yielded","natural_volume_street","natural_ledger_street"].some(storyFlag)) return true;
  const w = typeof pickUnifiedStoryWinner === "function" ? pickUnifiedStoryWinner() : null;
  return !!(w && ["volume_natural","ledger_natural","av_handoff","vl_handoff","volume_beat_prop"].includes(w.id));
}

